-- =========================================================
-- 0097b · LICEU: planificarea clasei 10D, pe orarul din 21 septembrie
--
-- Una din cinci. Se rulează în ordine: 0097a, 0097b, 0097c, 0097d, 0097e.
-- Ultima ține paza pe toate cinci deodată.
--
-- DE CE CINCI FIȘIERE, NU UNUL. Întregul făcea 297 KB, iar SQL Editor îl
-- refuză: „request entity too large". Pe clasă iese vreo 53 KB și intră.
--
-- Punctul de pornire e `Diverse/ORAR 21 SEPT/Planificatoare/`, exportul din
-- planificatorul lui Marius. El e adevărul; documentele Word se nasc din el.
--
-- CE SE SCHIMBĂ, la toate cinci (comparat amprentă cu amprentă, nu din ochi):
--   · 9B și 11D — neschimbate. Intră totuși, ca regula să n-aibă excepții de
--     ținut minte, iar ce iese e la fel cu ce era.
--   · 11C și 11D — își mută ora de vineri, de pe 21 sept. încolo (11C de la
--     11:25 la 10:35, 11D de la 10:35 la 11:25).
--   · 10D — recapitularea inițială scade de la 4 ore la 3, „Unitatea 1. Basmul
--     cult" începe la ora 4 în loc de 5, iar cele două lecții care stăteau
--     împreună la ora 6 se despart în orele 5 și 6.
--   · 11B — se schimbă unitățile 2 și 3 (orele 21–56). Primele 20 rămân.
--   · 11C — plan nou din temelii: are acum exact planul lui 11D.
--
-- 12C ȘI 12D NU SE ATING: ele merg pe planificarea de bacalaureat (0093).
--
-- ZIUA SE SCRIE FĂRĂ DIACRITICE („marti"), ca în orar: îmbinarea dintre
-- planificare și orar se face pe ea, iar o literă deosebită ar fi rupt-o în
-- tăcere.
--
-- `blocuri` SE ȚINE CIUNTIT: rămân numele, sursa, unitatea și competențele; se
-- lasă afară `notiuni`, `activitati` și `ideeaDeRetinut` — materialul de predare,
-- nouă zecimi din greutate, pe care modulul nu-l citește nicăieri. El rămâne
-- întreg în JSON-urile din `Diverse/ORAR 21 SEPT/`.
--
-- SE ȘTERGE ȘI SE SCRIE LA LOC. Un `update` rând cu rând ar fi lăsat în urmă
-- orele care nu mai există, iar cheia unică (clasă, an, dată, ceas) s-ar fi
-- lovit de ele la 11C și 11D, unde ceasul se mută.
-- =========================================================

delete from public.school_plan where clasa = '10D' and an_scolar = '2026-2027';


-- ---------- paza pe clasa asta ----------
do $$
declare n int; lipsa int;
begin
  select count(*) into n from public.school_plan where clasa = '10D' and an_scolar = '2026-2027';
  if n <> 95 then
    raise exception 'Clasa 10D are % ore, așteptam 95. Lipirea s-a rupt.', n;
  end if;
  select count(*) into lipsa from generate_series(1, 95) g
   where not exists (select 1 from public.school_plan p
                      where p.clasa = '10D' and p.an_scolar = '2026-2027' and p.nr = g);
  if lipsa > 0 then
    raise exception 'Clasei 10D îi lipsesc % numere din șirul 1..95.', lipsa;
  end if;
  raise notice 'Clasa 10D: 95 de ore, la locul lor.';
end $$;
